fibonacci &lt;- function(dataframe, x) {
  vetor &lt;- dataframe[, x]
  soma &lt;- rep(0, length(vetor))
  for (j in 1:length(vetor)) {
    a &lt;- 0
    b &lt;- 1
    num &lt;- a+b
    soma[j] &lt;- 0
    for (i in 1:vetor[j]) {
      num &lt;- a+b
      a &lt;- b
      b &lt;- num
      soma[j] &lt;- soma[j]+a
    }
  }
  return(soma)
}






